questionvariables.text:
/* helpers: relation tokens, display strings, inequality builders */
relt(r) := if r="lt" then "\\lt" else if r="le" then "\\le" else if r="gt" then "\\gt" else "\\ge";
reluc(r) := if r="lt" then "<" else if r="le" then "≤" else if r="gt" then ">" else "≥";
relflip(r) := if r="lt" then "gt" else if r="le" then "ge" else if r="gt" then "lt" else "le";
relother(r) := if r="lt" then "le" else if r="le" then "lt" else if r="gt" then "ge" else "gt";
relcomp(r) := if r="lt" then "ge" else if r="le" then "gt" else if r="gt" then "le" else "lt";
strictp(r) := is(r="lt" or r="gt");
/* Typed answers must be one inequality; "and"/"or" statements are rejected at validation. */
vsingle(ex) := if not atom(ex) and member(op(ex), ["and", "or", "nounand", "nounor"]) then "Type a single inequality, without the words and or or." else "";
mkin(u, r, w) := if r="lt" then u<w else if r="le" then u<=w else if r="gt" then u>w else u>=w;
holds(u, r, w) := if r="lt" then is(u<w) else if r="le" then is(u<=w) else if r="gt" then is(u>w) else is(u>=w);
relopts(c) := [["lt",is(c="lt"),"<"],["le",is(c="le"),"≤"],["gt",is(c="gt"),">"],["ge",is(c="ge"),"≥"]];
termp(v) := block([dd], dd: denom(v), while is(mod(dd,2)=0) do dd: dd/2, while is(mod(dd,5)=0) do dd: dd/5, is(dd=1));
nd(v) := if integerp(v) then string(v) else if termp(v) then string(float(v))
  else sconcat(if is(v<0) then "-" else "", "\\frac{", string(abs(num(v))), "}{", string(denom(v)), "}");
ndm(v) := sconcat("\\(", nd(v), "\\)");
/* plain-text number for aria-labels (nd gives TeX fractions, which a screen reader reads raw) */
ndt(v) := if integerp(v) then string(v) else if termp(v) then string(float(v)) else sconcat(string(num(v)), "/", string(denom(v)));
trm(k, v, fst) := block([m, s], m: abs(k), s: if v="" then nd(m) else if m=1 then v else sconcat(nd(m), v),
  if fst then (if k<0 then sconcat("-", s) else s) else (if k<0 then sconcat(" - ", s) else sconcat(" + ", s)));
lfs(L) := block([s, t], s: "", for t in L do (if t[1]#0 then s: sconcat(s, trm(t[1], t[2], is(s="")))), if s="" then "0" else s);
ins(a, b, c, r) := sconcat(lfs([[a,"x"],[b,"y"]]), " ", relt(r), " ", nd(c));
ineqd(a, b, c, r) := sconcat("\\(", ins(a, b, c, r), "\\)");
lind(a, b, c) := sconcat("\\(", lfs([[a,"x"],[b,"y"]]), " = ", nd(c), "\\)");
ineqm(a, b, c, r) := mkin(a*x+b*y, r, c);
/* pool rows [sentence, letter, number display, relation, key words] */
pool: [
 ["A water tank on a roof in Machakos cannot hold more than 2000 litres. It holds \\(v\\) litres.", "v", "2000", "le", "cannot hold more than"],
 ["A farmer plants maize seeds at a depth of not less than 5 cm. One seed is planted \\(d\\) cm deep.", "d", "5", "ge", "not less than"],
 ["A lift in an office block in Nairobi carries a maximum of 13 people. There are \\(p\\) people in it.", "p", "13", "le", "a maximum of"],
 ["At a market in Kisii, mangoes lighter than 200 g are sold for juice. A juice mango weighs \\(m\\) g.", "m", "200", "lt", "lighter than"],
 ["More than 250 runners started a race in Iten. The number of runners was \\(n\\).", "n", "250", "gt", "more than"],
 ["A sack of potatoes sold as full must weigh no less than 50 kg. A full sack weighs \\(w\\) kg.", "w", "50", "ge", "no less than"],
 ["The temperature in Lodwar was above \\(35\\,^\\circ\\text{C}\\) all afternoon. The temperature was \\(t\\,^\\circ\\text{C}\\).", "t", "35", "gt", "above"],
 ["A kienyeji hen house may keep no more than 24 hens. It keeps \\(c\\) hens.", "c", "24", "le", "no more than"],
 ["A plot must have an area of at least 450 square metres before a house is built on it. A plot of \\(k\\) square metres is big enough.", "k", "450", "ge", "at least"],
 ["The small water slide at a park is only for children shorter than 120 cm. Wanjiru, \\(h\\) cm tall, may use it.", "h", "120", "lt", "shorter than"],
 ["A minimum of 25 learners must sign up for a trip to go ahead. The trip goes ahead with \\(n\\) learners.", "n", "25", "ge", "a minimum of"],
 ["Over 60 000 people visited the Nairobi Agricultural Show on Saturday. The number of visitors was \\(v\\).", "v", "60\\,000", "gt", "over"],
 ["Fewer than 40 matatus left the stage before 6 am. The number was \\(m\\).", "m", "40", "lt", "fewer than"],
 ["Near a school gate, drivers must keep below 30 km/h. A driver obeying this drives at \\(s\\) km/h.", "s", "30", "lt", "below"]];
/* Design: write an inequality for a rule, sign chosen from a list. Source: adapted from SMP GCSE Higher 1, Chapter 28, question A8.
   q11: sentence ids per row; every relation in every row position at least twice. */
q11: [[1,7,13,9],[4,11,1,8],[10,1,3,9],[13,7,3,6],[2,6,7,3],[5,14,2,4],[11,8,10,5],[14,6,7,13],[12,13,11,7],[8,11,3,5]];
ix: 1+rand(10);
ids: q11[ix];
tr: makelist(pool[ids[k]][4], k, 1, 4);
ro: makelist(relother(tr[k]), k, 1, 4);
rf: makelist(relflip(tr[k]), k, 1, 4);
rc: makelist(relcomp(tr[k]), k, 1, 4);
o1: relopts(tr[1]); o2: relopts(tr[2]); o3: relopts(tr[3]); o4: relopts(tr[4]);
/* words for feedback: le at most, ge at least, lt less than, gt more than */
wd(r) := if r="le" then "at most" else if r="ge" then "at least" else if r="lt" then "less than" else "more than";
